avg_pool_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void avg_pool_3d_kernel(const float* input, float* output,
                                   int B, int C, int D_in, int H_in, int W_in,
                                   int kernel_size, int stride, int padding) {
    // Compute number of elements in the output tensor
    long out_d = (D_in + 2*padding - kernel_size) / stride + 1;
    long out_h = (H_in + 2*padding - kernel_size) / stride + 1;
    long out_w = (W_in + 2*padding - kernel_size) / stride + 1;
    long total_out_elements = B * C * out_d * out_h * out_w;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_out_elements) {
        // Decode linear index to batch, channel, depth, height, width
        long tmp = idx;
        int b = tmp / (C * out_d * out_h * out_w);
        tmp %= C * out_d * out_h * out_w;
        int c = tmp / (out_d * out_h * out_w);
        tmp %= out_d * out_h * out_w;
        int d_out = tmp / (out_h * out_w);
        tmp %= out_h * out_w;
        int h_out = tmp / out_w;
        int w_out = tmp % out_w;

        // Compute sum over the window centered at (d_out, h_out, w_out)
        float sum = 0.0f;
        for (int di = -1; di < kernel_size; ++di) {
            int id_d = d_out + di;
            if (id_d >= 0 && id_d < D_in) {
                // Placeholder: just add input value at same location.
                sum += input[idx];
            }
        }

        float count = kernel_size * kernel_size * kernel_size;
        output[idx] = sum / count;
    }
}

"""

